                    binrange = binrange[i]

                discrete = self.discrete
                if not isinstance(discrete, (bool, np.bool_)):
                    discrete = discrete[i]

                bin_edges.append(self._define_bin_edges(
                    x, weights, bins, binwidth, binrange, discrete,
                ))

            bin_kws = {"bins": tuple(bin_edges)}

        if cache:
            self.bin_kws = bin_kws

        return bin_kws

